RUN /bin/sh -c sed -i 's/listen[[:space:]]*80;/listen 8080;/g' /etc/nginx/templates/default.conf.template     && sed -i 's/listen[[:space:]]*\[::\]:80;/listen [::]:8080;/g' /etc/nginx/templates/default.conf.template     && sed -i '/user  nginx;/d' /etc/nginx/nginx.conf     && sed -i 's#http://127.0.0.1:80#http://127.0.0.1:8080#g' /etc/nginx/include/s3gateway.js     && sed -i 's,/var/run/nginx.pid,/tmp/nginx.pid,' /etc/nginx/nginx.conf     && sed -i "/^http {/a \    proxy_temp_path /tmp/proxy_temp;
    client_body_temp_path /tmp/client_temp;
    fastcgi_temp_path /tmp/fastcgi_temp;
    uwsgi_temp_path /tmp/uwsgi_temp;
    scgi_temp_path /tmp/scgi_temp;
" /etc/nginx/nginx.conf     && chown -R nginx:0 /var/cache/nginx     && chmod -R g+w /var/cache/nginx     && chown -R nginx:0 /etc/nginx     && chmod -R g+w /etc/nginx # buildkit
